SET ROLE service_role;
DO $$
DECLARE customer uuid:='10000000-0000-4000-8000-000000000001';admin uuid:='10000000-0000-4000-8000-000000000002';other_customer uuid:='10000000-0000-4000-8000-000000000003';
 items jsonb:='[{"id":"30000000-0000-4000-8000-000000000001","name":"架空カードA","cardNumber":"001","quantity":2,"grade":"未鑑定","condition":"白欠けあり","source":"manual","productId":null,"cardUid":null},{"id":"30000000-0000-4000-8000-000000000002","name":"架空カードB","cardNumber":"002","quantity":1,"grade":"その他鑑定","condition":"要検品","source":"snkrdunk","productId":"123","cardUid":null}]';
 inspection jsonb:='[{"id":"30000000-0000-4000-8000-000000000001","quantity":2,"location":"BUNDLE-PRIVATE-A","checked":true},{"id":"30000000-0000-4000-8000-000000000002","quantity":1,"location":"BUNDLE-PRIVATE-B","checked":true}]';
 draft jsonb; c jsonb; l jsonb; replay jsonb; k uuid:=gen_random_uuid();cid uuid;lid uuid;payoff bigint;v integer;
BEGIN
 draft:=jsonb_build_object('reason','other','cardName','caller summary ignored','cardNumber','','condition','','notes','LOCAL BUNDLE TEST','requestedAmount','300000','consent',true,'items',items);
 ASSERT lending_collateral_valid(items);ASSERT NOT lending_collateral_valid(jsonb_set(items,'{0,quantity}','101'));ASSERT NOT lending_collateral_valid(items||items);
 c:=lending_support_create(customer,draft,k);cid:=(c->>'id')::uuid;
 ASSERT c->'collateral_items'=items AND c->>'card_name' LIKE '%合計3枚';
 ASSERT lending_support_create(customer,draft,k)=c;
 BEGIN PERFORM lending_support_create(customer,jsonb_set(draft,'{items,0,quantity}','1'),k);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='idempotency_conflict';END;
 BEGIN PERFORM lending_support_create(customer,jsonb_set(draft,'{items,0,quantity}','101'),gen_random_uuid());RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='collateral_invalid';END;
 BEGIN UPDATE lending_support_cases SET collateral_items='[]' WHERE id=cid;RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='collateral_immutable';END;
 ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(lending_support_list(other_customer)->'cases') e WHERE e->>'id'=cid::text);
 PERFORM lending_support_command(admin,cid,'review','{"message":"全明細を確認"}',gen_random_uuid(),1);
 PERFORM lending_support_command(admin,cid,'offer','{"amountJpy":300000,"valuationJpy":500000,"message":"3枚まとめた見積もり"}',gen_random_uuid(),2);
 c:=lending_support_command(customer,cid,'accept','{"amountJpy":300000,"deposit":"mail","termsAccepted":true}',gen_random_uuid(),3);lid:=(c->>'loan_id')::uuid;
 ASSERT (SELECT count(*)=1 FROM lending_loans WHERE id=lid AND collateral_items=items);
 ASSERT (SELECT collateral_items=items FROM lending_quotes WHERE id=(SELECT quote_id FROM lending_loans WHERE id=lid));
 BEGIN PERFORM lending_command(admin,lid,'receive','{"location":"COMMON","inspected":true}',gen_random_uuid(),1);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='collateral_inspection_required';END;
 BEGIN PERFORM lending_command(admin,lid,'receive',jsonb_build_object('location','COMMON','inspected',true,'collateralInspection',jsonb_set(inspection,'{0,quantity}','1')),gen_random_uuid(),1);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='collateral_inspection_required';END;
 ASSERT (SELECT version=1 AND status='submitted' FROM lending_loans WHERE id=lid);
 k:=gen_random_uuid();l:=lending_command(admin,lid,'receive',jsonb_build_object('location','COMMON','inspected',true,'collateralInspection',inspection),k,1);
 replay:=lending_command(admin,lid,'receive',jsonb_build_object('location','COMMON','inspected',true,'collateralInspection',inspection),k,1);ASSERT replay=l;
 ASSERT lending_admin_detail(admin,'loan',lid)->'item'->'collateral_inspection'=inspection;
 SELECT e INTO l FROM jsonb_array_elements(lending_list(customer)->'loans') e WHERE e->>'id'=lid::text;
 ASSERT l->'collateral_items'=items AND NOT l ? 'collateral_inspection' AND l->>'storage_location' IS NULL;
 PERFORM lending_command(admin,lid,'offer','{"amountJpy":300000,"monthlyRateBps":200,"manualValuationJpy":500000,"manualCapJpy":300000,"reason":"3枚全体の現物評価"}',gen_random_uuid(),2);
 ASSERT (SELECT terms->'collateralItems'=items FROM lending_loans WHERE id=lid);
 ASSERT (SELECT details->'termsSnapshot'->'collateralItems'=items FROM lending_events WHERE loan_id=lid AND action='offer');
 PERFORM lending_command(customer,lid,'accept','{"termsAccepted":true}',gen_random_uuid(),3);
 PERFORM lending_command(admin,lid,'fund','{"amountJpy":300000,"reference":"BUNDLE-FUND-001"}',gen_random_uuid(),4);
 ASSERT (SELECT count(*)=1 AND sum(amount_jpy)=300000 FROM lending_ledger WHERE loan_id=lid AND kind='disbursement');
 SELECT (e->>'payoff_jpy')::bigint INTO payoff FROM jsonb_array_elements(lending_list(customer)->'loans') e WHERE e->>'id'=lid::text;
 PERFORM lending_command(customer,lid,'report_repayment','{}',gen_random_uuid(),5);
 PERFORM lending_command(admin,lid,'confirm_repayment',jsonb_build_object('amountJpy',payoff,'reference','BUNDLE-REPAY-001'),gen_random_uuid(),6);
 BEGIN PERFORM lending_command(admin,lid,'return','{"reference":"BUNDLE-RETURN-001"}',gen_random_uuid(),7);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='all_items_return_required';END;
 PERFORM lending_command(admin,lid,'return','{"reference":"BUNDLE-RETURN-001","allItemsReturned":true}',gen_random_uuid(),7);
 ASSERT (SELECT status='returned' AND principal_jpy=0 FROM lending_loans WHERE id=lid);
 ASSERT (SELECT count(*)=1 FROM lending_status_notifications WHERE entity_id=lid AND to_status='active');
 RAISE NOTICE 'Bundle: immutable items, bounds, owner isolation, one loan/ledger, every-line inspection, consent snapshot and full return passed.';
END $$;
RESET ROLE;
SET ROLE authenticated;
DO $$ BEGIN
 BEGIN PERFORM lending_collateral_valid('[]');RAISE EXCEPTION 'unsafe helper';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;
